fn queue_at<'a>(
    queues: &'a mut BTreeMap<QueueName, Queue>,
    name: &str,
    now: Instant,
) -> Result<&'a mut Queue, ApiError> {
    let queue = queues.get_mut(name).ok_or_else(|| no_such_queue(name))?;
