        .stdout(Stdio::piped())
        .spawn()
        .unwrap();
    child
        .stdin
        .take()
        .unwrap()
        .write_all(b"{\"Command\":\"Tick\",\"Seconds\":3}")
        .unwrap();
    let output = child.wait_with_output().unwrap();
    assert!(output.status.success());
