        create("std"),
        create_with("b.fifo", json!({"Fifo": true, "DeadLetterQueue": "std", "MaxReceiveCount": 2})),
        create_with("std", json!({"DeadLetterQueue": "missing", "MaxReceiveCount": 2})),
    ]);
    assert_eq!(
        responses,
        vec![
            failure("InvalidParameterValue"),
            failure("InvalidParameterValue"),
            failure("QueueDoesNotExist"),
